package org.sleepwell.app;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;

public final class AlarmSoundModeTest {
    static class Fake extends AlarmPlaybackTest.Fake {int saved;String run="owned";public String occurrence(){return run;}public int position(String key){return saved;}public AlarmPlayback.Layer create(String source,boolean loop,String key,int position){Layer layer=(Layer)create(source);layer.loop=loop;layer.key=key;layer.position=position;return layer;}}
    Alarm alarm(){Alarm a=new Alarm(1);a.rampSeconds=0;a.soundMode=new AlarmSoundMode(AlarmSoundMode.Kind.PLAYLIST,List.of("daybreak","pulse","chime"),false);return a;}
    AlarmPlayback engine(Alarm a,Fake f){return new AlarmPlayback(a,f,()->f.now,()->f.now);}
    @Test public void defaultSingleTonePreservesLoopingAndNoCompletionSequence(){Alarm a=new Alarm(1);assertEquals(AlarmSoundMode.SINGLE,a.soundMode);Fake f=new Fake();engine(a,f).start();assertTrue(f.layers.get(0).loop);assertNull(f.layers.get(0).complete);}
    @Test public void explicitSilentNeverAllocatesEvenAfterBackupDelayErrorsOrRepeatedStarts(){Alarm a=alarm();a.soundMode=AlarmSoundMode.SILENT;Fake f=new Fake(){public AlarmPlayback.Layer create(String tone){throw new AssertionError("Silent cannot create output or fallback");}};AlarmPlayback e=engine(a,f);e.start(true);e.backup();e.backup(false);f.now=Long.MAX_VALUE;e.tick();e.start();e.stop();assertTrue(f.layers.isEmpty());assertEquals(0,f.errors);}
    @Test public void completionDrivesOrderedCyclicPlaylistAndOldCallbacksCannotAdvance(){Fake f=new Fake();AlarmPlayback e=engine(alarm(),f);e.start();assertFalse(f.layers.get(0).loop);for(int n=0;n<4;n++){Fake.Layer layer=f.layers.get(n);assertEquals(List.of("daybreak","pulse","chime","daybreak").get(n),layer.tone);assertEquals(n%3,layer.position);layer.callback.ready();assertEquals(1,layer.starts);layer.complete.run();int count=f.layers.size();layer.complete.run();assertEquals(count,f.layers.size());assertTrue(layer.closed);}e.stop();int count=f.layers.size();f.layers.get(4).callback.ready();assertEquals(count,f.layers.size());assertEquals(0,f.layers.get(4).starts);}
    @Test public void savedPositionResumesLastStartedTrackAndMalformedPositionStartsAtZero(){Fake f=new Fake();f.saved=2;engine(alarm(),f).start();assertEquals("chime",f.layers.get(0).tone);Fake bad=new Fake();bad.saved=999;engine(alarm(),bad).start();assertEquals("daybreak",bad.layers.get(0).tone);}
    @Test public void deterministicShuffleHasEveryTrackOnceAndPreservesSameOccurrence(){AlarmSoundMode mode=new AlarmSoundMode(AlarmSoundMode.Kind.PLAYLIST,List.of("daybreak","pulse","chime","system"),true);AlarmSoundSequence a=new AlarmSoundSequence(mode,"run",0),b=new AlarmSoundSequence(mode,"run",2);assertEquals(a.order,b.order);assertEquals(new HashSet<>(mode.tracks),new HashSet<>(a.order));assertEquals(4,a.order.size());assertEquals(a.order.get(2),b.current());assertNotEquals(a.key,new AlarmSoundSequence(new AlarmSoundMode(AlarmSoundMode.Kind.PLAYLIST,mode.tracks,false),"run",0).key);}
    @Test public void inaccessibleEntriesAreSkippedOnceThenSingleSafeFallbackIsBounded(){Fake f=new Fake();AlarmPlayback e=engine(alarm(),f);e.start();for(int n=0;n<3;n++){assertEquals(List.of("daybreak","pulse","chime").get(n),f.layers.get(n).tone);f.layers.get(n).callback.failed();}assertEquals(4,f.layers.size());assertEquals("daybreak",f.layers.get(3).tone);assertTrue(f.layers.get(3).loop);assertNull(f.layers.get(3).complete);f.layers.get(3).callback.failed();e.tick();assertEquals(4,f.layers.size());assertEquals(1,f.errors);}
    @Test public void backupInterruptsSequenceAndEndsAtSameTrackWithoutAcceptingOldCompletion(){Fake f=new Fake();AlarmPlayback e=engine(alarm(),f);e.start();Fake.Layer original=f.layers.get(0);original.callback.ready();e.backup();original.complete.run();assertEquals(2,f.layers.size());f.layers.get(1).callback.ready();assertTrue(original.closed);e.backup(false);assertEquals("daybreak",f.layers.get(2).tone);f.layers.get(2).callback.ready();f.layers.get(2).complete.run();assertEquals("pulse",f.layers.get(3).tone);}
    @Test public void failedBackupKeepsSequentialPrimaryWorkingAtEscalatedEnvelope(){Fake f=new Fake();AlarmPlayback e=engine(alarm(),f);e.start();Fake.Layer primary=f.layers.get(0);primary.callback.ready();e.backup();f.layers.get(1).callback.failed();assertFalse(primary.closed);primary.complete.run();assertEquals(3,f.layers.size());assertEquals("pulse",f.layers.get(2).tone);assertFalse(f.layers.get(2).loop);}
    @Test public void primaryCompletionDuringPendingBackupIsConsumedOnceWhenReplacementFails(){Fake f=new Fake();AlarmPlayback e=engine(alarm(),f);e.start();Fake.Layer primary=f.layers.get(0);primary.callback.ready();e.backup();primary.complete.run();assertEquals(2,f.layers.size());f.layers.get(1).callback.failed();assertEquals(3,f.layers.size());assertEquals("pulse",f.layers.get(2).tone);assertFalse(f.layers.get(2).loop);primary.complete.run();assertEquals(3,f.layers.size());}
    @Test public void activeTrackDecodeErrorSkipsForwardRatherThanRestartingWholeList(){Fake f=new Fake();AlarmPlayback e=engine(alarm(),f);e.start();f.layers.get(0).callback.ready();f.layers.get(0).callback.failed();assertEquals("pulse",f.layers.get(1).tone);f.layers.get(1).callback.ready();f.layers.get(1).complete.run();assertEquals("chime",f.layers.get(2).tone);}
    @Test public void immutableTemplateCopiesPreserveSourcesWithoutScheduleAuthority(){Alarm a=alarm();a.soundMode=new AlarmSoundMode(AlarmSoundMode.Kind.PLAYLIST,List.of("daybreak","content://inert.audio/private"),true);Alarm fresh=new AlarmDefaults(a).create(9);assertEquals(a.soundMode,fresh.soundMode);assertFalse(fresh.enabled);assertTrue(new AlarmDefaults(a).references("content://inert.audio/private"));assertThrows(UnsupportedOperationException.class,()->a.soundMode.tracks.add("pulse"));a.soundMode=AlarmSoundMode.SILENT;assertTrue(new AlarmDefaults(a).create(10).soundMode.silent());}
    @Test public void failedProviderIsAttemptedOnlyOncePerOccurrenceEvenAcrossManyGoodCompletions(){Alarm a=alarm();a.soundMode=new AlarmSoundMode(AlarmSoundMode.Kind.PLAYLIST,List.of("content://blocked.provider/audio","daybreak"),false);Fake f=new Fake();AlarmPlayback e=engine(a,f);e.start();f.now=4000;e.tick();assertTrue(f.layers.get(0).closed);for(int n=1;n<=50;n++){Fake.Layer layer=f.layers.get(n);assertEquals("daybreak",layer.tone);layer.callback.ready();layer.complete.run();}assertEquals(1,f.layers.stream().filter(layer->layer.tone.startsWith("content:")).count());e.backup();f.layers.get(f.layers.size()-1).callback.ready();e.backup(false);assertEquals("daybreak",f.layers.get(f.layers.size()-1).tone);assertEquals(1,f.layers.stream().filter(layer->layer.tone.startsWith("content:")).count());e.stop();assertTrue(f.layers.stream().allMatch(layer->layer.closed));}
    @Test public void importedNamesFollowReorderingAndRemovalWithoutChangingSources(){AlarmSoundMode initial=new AlarmSoundMode(AlarmSoundMode.Kind.PLAYLIST,List.of("daybreak","pulse"),false);AlarmSoundMode named=initial.add("content://owned.audio/file","My dawn");assertEquals("My dawn",named.name("content://owned.audio/file"));AlarmSoundMode ordered=named.changed(List.of("content://owned.audio/file","daybreak"),true);assertEquals("My dawn",ordered.name(ordered.tracks.get(0)));assertTrue(ordered.changed(List.of("daybreak","pulse"),false).names.isEmpty());assertEquals(2,initial.tracks.size());}
    @Test public void supportedBoundsRejectDuplicatesAndNonContentProviders(){assertThrows(IllegalArgumentException.class,()->new AlarmSoundMode(AlarmSoundMode.Kind.PLAYLIST,List.of("daybreak"),false));assertThrows(IllegalArgumentException.class,()->new AlarmSoundMode(AlarmSoundMode.Kind.PLAYLIST,List.of("daybreak","daybreak"),false));for(String value:new String[]{"http://a/b","file:///a.wav","content:/noauthority","content://a/b#fragment","unknown"})assertFalse(AlarmSoundMode.source(value));assertTrue(AlarmSoundMode.source("content://owned.provider/audio/1"));assertThrows(IllegalArgumentException.class,()->new AlarmSoundMode(AlarmSoundMode.Kind.SILENT,List.of("daybreak"),false));}
}
